  padding-block:var(--s3);min-height:48px;color:var(--ink);text-decoration:none;transition:color var(--d-fast) var(--e-out)}
.hi-n{font-family:"Instrument Serif",Georgia,serif;font-size:19px;color:var(--accent)}
.hi-t{font-size:var(--t-sm);font-weight:500;line-height:1.4}
