@media (max-width:420px){.hero-index{padding:var(--s4)}.hero-index a{grid-template-columns:28px minmax(0,1fr)}.hi-c{grid-column:2;text-align:left;margin-top:-6px}}

/* --- rejilla de automatizaciones en la portada --- */
.auto-grid{list-style:none;margin:var(--s7) 0 0;padding:0;display:grid;gap:var(--s5);grid-template-columns:repeat(4,minmax(0,1fr))}
@media (max-width:1060px){.auto-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:560px){.auto-grid{grid-template-columns:1fr;gap:var(--s4)}}
.card{position:relative;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--rule);
  border-radius:var(--r-l);padding:var(--s3) var(--s3) var(--s4);transition:border-color var(--d-base) var(--e-out)}
.card:not(.card-cta):hover{border-color:var(--rule-field)}
.card-shot{border:1px solid var(--rule);border-radius:var(--r-m);overflow:hidden;background:var(--sunk);aspect-ratio:16/10}
.card-shot img{width:100%;height:100%;object-fit:cover;object-position:top left;transition:transform var(--d-enter) var(--e-out)}
.card:hover .card-shot img{transform:scale(1.02)}
.card-k{margin:var(--s4) var(--s2) var(--s1);font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint)}
.card h3{margin-inline:var(--s2);font-size:19px;line-height:1.3}
.card h3 a{color:var(--ink);text-decoration:none}
.card h3 a::after{content:"";position:absolute;inset:0;border-radius:inherit}   /* toda la tarjeta es el enlace */
.card h3 a:focus-visible{outline:0}
.card:has(h3 a:focus-visible){outline:2px solid var(--accent);outline-offset:2px}
.card:hover h3 a{color:var(--accent)}
.card>p:not(.card-k){margin:var(--s2) var(--s2) 0;font-size:var(--t-sm);line-height:1.55;color:var(--muted)}
.card .card-meta{margin-top:auto;padding-top:var(--s4);font-size:var(--t-xs);color:var(--text)}
.card-meta span:first-child{letter-spacing:.1em;text-transform:uppercase;font-size:11px;color:var(--faint);margin-right:6px}
.card-cta{background:var(--sunk);padding:var(--s5);justify-content:center}
.card-cta h3{margin:0;font-family:"Instrument Serif",Georgia,serif;font-weight:400;font-size:26px;letter-spacing:-.01em;line-height:1.15}
.card-cta>p{margin:var(--s3) 0 0!important}
.card-cta-links{display:flex;flex-direction:column;align-items:flex-start;gap:var(--s4);margin-top:var(--s5)}

/* --- demos --- */
.demo-copy .detects-label{margin-top:var(--s5);margin-bottom:var(--s3)}
.demo-more{margin-top:var(--s5)}

/* --- pestañas de precios --- */
.tabs{display:flex;flex-wrap:wrap;gap:var(--s2);margin-top:var(--s6)}
.tabs [role="tab"]{min-height:44px;padding:0 18px;border:1px solid var(--rule-field);border-radius:999px;background:var(--surface);
  color:var(--text);font:500 var(--t-sm)/1.2 "IBM Plex Sans",sans-serif;cursor:pointer;
  transition:background var(--d-base) var(--e-out),color var(--d-base) var(--e-out),border-color var(--d-base) var(--e-out)}
.tabs [role="tab"]:hover{border-color:var(--ink);color:var(--ink)}
.tabs [role="tab"][aria-selected="true"]{background:var(--ink);border-color:var(--ink);color:var(--paper)}
html:not(.js) .tabs{display:none}
.tabpanel .plans{margin-top:var(--s5)}
.js .tabpanel-title{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
html:not(.js) .tabpanel{margin-top:var(--s7)}
.tabpanel[hidden]{display:none}
.tabpanel:not([hidden]){animation:faq-in var(--d-enter) var(--e-out) both}
.plan li b{color:var(--ink);font-weight:600}

/* --- catálogo de automatizaciones --- */
.cat-hero{padding-block:var(--s8) var(--s7);border-top:0}
.cat-hero h1{max-width:18ch}
.cat-hero .lead{margin-top:var(--s4)}
.cat-list{padding-block:var(--s7) var(--s8)}
.autos{display:grid;gap:var(--s5);grid-template-columns:repeat(2,minmax(0,1fr))}
@media (max-width:860px){.autos{grid-template-columns:1fr}}
.auto{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--rule);
  border-radius:var(--r-l);padding:var(--s3) var(--s5) var(--s5)}
.auto-shot{border:1px solid var(--rule);border-radius:var(--r-m);overflow:hidden;background:var(--sunk);aspect-ratio:16/10;
  margin:0 calc(var(--s2) - var(--s5)) var(--s5)}
.auto-shot img{width:100%;height:100%;object-fit:cover;object-position:top left}
.auto>.eyebrow{margin-bottom:var(--s3);font-size:12px;color:var(--faint)}
.auto h2{font-size:26px;font-family:"Instrument Serif","Iowan Old Style",Georgia,serif;
  font-weight:400;letter-spacing:-.01em;max-width:none;margin-bottom:var(--s3)}
.auto>p:not(.eyebrow){color:var(--text);font-size:var(--t-sm);line-height:1.6}
.auto .checklist{margin-top:var(--s4);font-size:var(--t-xs)}
.auto .checklist li{grid-template-columns:minmax(110px,auto) 1fr;gap:var(--s3)}
.auto .checklist li b{color:var(--ink);font-weight:500}
.auto-meta{display:grid;gap:0;margin:var(--s4) 0 var(--s5)}
.auto-meta>div{display:grid;grid-template-columns:minmax(80px,auto) 1fr;gap:var(--s3);
  padding-block:var(--s2);border-bottom:1px solid var(--rule)}
.auto-meta dt{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);padding-top:3px}
.auto-meta dd{margin:0;font-size:var(--t-sm);color:var(--text)}
.auto-links{margin-top:auto;display:flex;flex-wrap:wrap;align-items:center;gap:var(--s3) var(--s5)}
.auto-links .btn{min-height:44px;font-size:var(--t-sm)}
.auto-links .link-arrow{font-size:var(--t-sm)}
.auto-cta{background:var(--sunk);justify-content:center;padding:var(--s6)}
.auto-cta h2{font-size:30px;max-width:24ch}
.auto-cta>p{color:var(--muted);font-size:var(--t-sm);margin-top:var(--s3)}
.auto-cta .cta-row{margin-top:var(--s5)}
@media (max-width:520px){.auto{padding:var(--s2) var(--s4) var(--s5)}.auto-shot{margin-inline:calc(var(--s2) - var(--s4))}.auto-cta{padding:var(--s5)}}
.demo-copy .facts>div{grid-template-columns:132px minmax(0,1fr)}
.plan ul{align-content:start}
@media (max-width:999px){.home-page .hero-index{display:none}}
@media (max-width:420px){.hero-index-head span+span{display:none}}

/* ---- panel ---- */
/* ============================================================
   Panel de cliente y administración de Denoro.
   Va DESPUÉS de la hoja de estilos de la web (web/src/styles.css): mismos tokens,
   misma tipografía, mismos botones y formularios. Aquí solo lo que la web no tiene
   (pestañas, tablas, estados) dibujado con el mismo lenguaje: papel, filete de 1 px, un acento.
   ============================================================ */
body.app{min-height:100vh;display:flex;flex-direction:column}
body.app main{flex:1}
body.app>header .wrap{gap:var(--s4)}
.who{margin-left:auto;display:flex;align-items:center;gap:var(--s3);min-width:0}
.who .hint{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:36ch}
@media (max-width:620px){.who .hint{display:none}}

/* --- cabecera de página --- */
.p-hero{padding-block:var(--s7) var(--s5)}
.p-hero h1{font-size:clamp(34px,4.6vw,52px);max-width:22ch}
.p-hero .lead{margin-top:var(--s3)}
.p-hero .facts{margin-top:var(--s5);max-width:760px}
@media (min-width:720px){.p-hero .facts{grid-template-columns:repeat(3,1fr);border-top:1px solid var(--rule)}
  .p-hero .facts>div{grid-template-columns:1fr;gap:2px;padding-right:var(--s4)}
  .p-hero .facts>div+div{border-left:1px solid var(--rule);padding-left:var(--s4)}}
.facts .big{font-family:"Instrument Serif",Georgia,serif;font-size:34px;line-height:1.05;color:var(--ink);letter-spacing:-.02em;font-weight:400}

/* --- pestañas (mismo subrayado que la navegación de la web) --- */
.tabs{display:flex;gap:var(--s5);border-bottom:1px solid var(--rule);overflow-x:auto;scrollbar-width:none;
  margin-bottom:var(--s6);position:sticky;top:68px;z-index:5;background:color-mix(in srgb,var(--paper) 92%,transparent);backdrop-filter:blur(10px)}
.tabs::-webkit-scrollbar{display:none}
.tab{border:0;background:none;padding:14px 0 13px;font:inherit;font-size:var(--t-sm);color:var(--muted);cursor:pointer;
  white-space:nowrap;display:inline-flex;align-items:center;gap:8px;transition:color var(--d-fast) var(--e-out);min-height:48px}
.tab:hover{color:var(--ink)}
.tab[aria-selected="true"]{color:var(--ink);box-shadow:inset 0 -2px 0 var(--accent)}
.tab .dot{width:7px;height:7px;border-radius:50%;background:var(--rule-strong);flex:none}
.tab .dot.ok{background:var(--ok)}.tab .dot.bad{background:var(--alert)}.tab .dot.info{background:var(--accent)}
[role="tabpanel"]{padding-bottom:var(--s8)}
[role="tabpanel"]:focus-visible{outline:none}

/* --- rejillas --- */
.p-grid{display:grid;gap:var(--s5);align-items:start}
@media (min-width:980px){.p-grid{grid-template-columns:minmax(0,1fr) 360px;gap:var(--s6)}
  .p-side{position:sticky;top:136px}}
.p-card{background:var(--surface);border:1px solid var(--rule);border-radius:var(--r-l);padding:var(--s6)}
.p-card.sunk{background:var(--sunk)}
@media (max-width:520px){.p-card{padding:var(--s5) var(--s4)}}
.p-card+.p-card{margin-top:var(--s5)}
.p-card>.eyebrow{margin-bottom:var(--s3)}
.p-card h2{font-size:var(--t-h3);max-width:none;letter-spacing:-.01em}
.p-card h2+p,.p-card h3+p{margin-top:var(--s2);color:var(--muted);font-size:var(--t-sm);max-width:62ch}
