@media (min-width:640px){.fgrid{grid-template-columns:1fr 1fr}.fgrid .full{grid-column:1/-1}}
.check{display:flex;gap:12px;align-items:flex-start;padding-block:10px;cursor:pointer;
  font-size:var(--t-sm);line-height:1.5;color:var(--text);text-transform:none;letter-spacing:0;margin:0}
