.btn.sm{min-height:40px;padding:0 14px;font-size:var(--t-sm)}
.btn.full{width:100%}
.btn.danger{color:var(--alert)}
.btn.danger:hover{border-color:var(--alert);background:var(--alert-tint)}
.inline{display:flex;gap:var(--s3);align-items:flex-end}
.inline>*{flex:1}.inline>.btn{flex:none}
@media (max-width:560px){.inline{flex-direction:column;align-items:stretch}}
.subform{border:1px solid var(--rule);border-radius:var(--r-m);padding:var(--s4);background:var(--paper)}
.subform+.subform{margin-top:var(--s3)}
.subform-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:var(--s3)}
