/* --- estados --- */
.badge{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--rule);border-radius:999px;padding:3px 11px;
  font-size:13px;line-height:1.4;color:var(--muted);background:var(--surface);white-space:nowrap}
.badge.ok{background:var(--ok-tint);color:var(--ok);border-color:transparent}
