.note{font-size:var(--t-xs);color:var(--muted);margin-top:var(--s3);max-width:none}
.msg{font-size:var(--t-sm)}
.msg.warn{background:#f4eee1;color:#7a5a1c;border-color:transparent}

/* --- tarjetas del resumen (las del catálogo de la web) --- */
.autos.panel{grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.auto .auto-state{display:flex;gap:var(--s2);align-items:center;flex-wrap:wrap;margin:0 0 var(--s3)}
.auto button.link-arrow{background:none;border:0;border-bottom:1px solid currentColor;cursor:pointer;font:inherit;font-weight:500;padding:0 0 2px}
.auto .auto-meta{margin-top:auto;margin-bottom:var(--s4)}
.auto>p{margin-bottom:var(--s4)}

/* --- tablas --- */
.tbl-wrap{overflow-x:auto;margin-inline:calc(-1 * var(--s2))}
table.tbl{width:100%;border-collapse:collapse;font-size:var(--t-sm)}
.tbl th{font-size:12px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);text-align:left;
