.tbl tr.edit td{background:var(--sunk);padding-top:0}
.num{font-variant-numeric:tabular-nums}
.empty{padding:var(--s6) var(--s3);text-align:center;color:var(--muted);font-size:var(--t-sm)}
@media (max-width:640px){.hide-s{display:none}}

/* --- monitor: vista previa de lo detectado --- */
.preview{margin-top:var(--s4);border:1px solid var(--rule);border-radius:var(--r-m);overflow:hidden;background:var(--paper)}
.preview-head{padding:var(--s3) var(--s4);background:var(--sunk);display:flex;gap:var(--s3);align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--rule)}
.preview-body{padding:var(--s2) var(--s4) var(--s4)}
.plist{list-style:none;margin:0;padding:0}
