        <h2>${esc(a.nombre)}</h2>
        <p>${esc(a.resumen)}</p>
        <p class="msg warn" data-demo hidden style="margin-bottom:var(--s5)">Está en modo prueba con datos de ejemplo: puedes ejecutarla y ver el resultado sin tocar nada real. Cuando quieras usar tus datos, cambia la fuente.</p>
        ${grupos.map((gr) => `<fieldset><legend>${esc(gr.t)}</legend><div class="fgrid">${gr.f.map((f) => campo(f, aj[f.k], 'x')).join('')}</div></fieldset>`).join('')}
        <fieldset><legend>Cuándo</legend><div class="fgrid">${cuando}</div></fieldset>
        <div class="actions"><button class="btn primary" id="saveAuto">Guardar cambios</button><span class="hint" id="dirty"></span></div>
        <div id="autoMsg"></div>
      </form>
      <aside class="p-side">
        <div class="p-card sunk">
          <p class="eyebrow">Estado</p>
          <span class="badge ${st.cls}">${esc(st.txt)}</span>
          <dl class="facts tight">
            <div><dt>Cuándo</dt><dd>${esc(cadaTxt(a, aj))}</dd></div>
            <div><dt>Última</dt><dd>${esc(res?.ultima ? ago(res.ultima) : 'todavía no')}</dd></div>
            <div><dt>Próxima</dt><dd>${esc(proxima(a, s))}</dd></div>
          </dl>
          <div class="actions" style="margin-top:var(--s4)">
            <button type="button" class="btn primary full" id="runAuto">Ejecutar ahora</button>
            ${a.cada.semanal ? `<button type="button" class="btn full" id="runResumen">Enviar el resumen semanal ahora</button>` : ''}
          </div>
          <p class="note">Usa lo que tengas guardado. El resultado sale aquí y te llega ${S.cliente.email || S.cliente.telegram_chat_id ? 'a tus avisos' : '(cuando configures tus avisos)'}.</p>
          <div id="runMsg"></div>
        </div>
        ${resultado(res, 'Último resultado')}
        ${resultado(resR, 'Último resumen semanal')}
      </aside>
    </div>`;
    const form = $('autoForm');
    aplicarVisibilidad(form);
    let dirty = false;
    const marcar = () => { if (!dirty) { dirty = true; $('dirty').textContent = 'Cambios sin guardar'; } };
    form.addEventListener('input', marcar);
    form.addEventListener('change', () => { marcar(); aplicarVisibilidad(form); });
    form.addEventListener('click', (e) => {
      const add = e.target.closest('[data-add]');
