        const box = del.closest('[data-list]'); del.closest('[data-item]').remove();
        box.querySelectorAll('[data-item] .subform-head b').forEach((b, i) => { b.textContent = `${box.dataset.list === 'pasos' ? 'Aviso' : 'Página'} ${i + 1}`; });
        marcar();
