    form.addEventListener('submit', async (e) => {
      e.preventDefault(); msg('autoMsg', '');
      await busy($('saveAuto'), 'Guardando', async () => {
        const r = await api('auto_guardar', { id, ajustes: leerForm(form, a) });
        if (!r.ok) return msg('autoMsg', r.error);
