    const run = async (btn, modo) => {
      msg('runMsg', '');
      if (dirty) return msg('runMsg', 'Tienes cambios sin guardar: guárdalos antes para que se usen.', 'warn');
      await busy(btn, 'Ejecutando', async () => {
        const r = await api('auto_ejecutar', { id, modo });
