    $('runAuto').addEventListener('click', (e) => run(e.currentTarget, 'vigilancia'));
    $('runResumen')?.addEventListener('click', (e) => run(e.currentTarget, 'resumen'));
  }

  // ---------------------------------------------------------------- pestaña del monitor
  function renderMonitor(p) {
    const s = servicio('monitor'); const r = s.estado || S.resumen; const st = estadoAuto(s);
    const w = S.vigilancias; const aj = S.ajustes;
    const productos = w.reduce((n, x) => n + (x.estado?.productos || 0), 0);
    p.innerHTML = `<div class="p-grid">
