          <div class="actions" style="margin-top:var(--s4)"><button type="button" class="btn primary full" id="checkNow">Revisar ahora</button></div>
          <div id="checkMsg"></div>
        </div>
        <form class="p-card" id="monForm">
          <p class="eyebrow">Ajustes del monitor</p>
          <div class="field"><label for="freq">Revisar cada</label><select id="freq">${[1, 3, 6, 12, 24].map((h) => `<option value="${h}"${aj.frecuencia_horas === h ? ' selected' : ''}>${horasTxt(h)}</option>`).join('')}</select></div>
          <div class="field"><label for="thr">Avisar a partir de un cambio del</label><select id="thr">${[[0, 'cualquier cambio'], [1, '1 %'], [3, '3 %'], [5, '5 %'], [10, '10 %']].concat([0, 1, 3, 5, 10].includes(aj.umbral_pct) ? [] : [[aj.umbral_pct, `${aj.umbral_pct} %`]]).map(([v, t]) => `<option value="${v}"${aj.umbral_pct === v ? ' selected' : ''}>${t}</option>`).join('')}</select></div>
          <label class="check"><input type="checkbox" id="optStock"${aj.avisar_stock ? ' checked' : ''}> <span>Cambios de stock</span></label>
          <label class="check"><input type="checkbox" id="optNew"${aj.avisar_nuevos ? ' checked' : ''}> <span>Productos nuevos</span></label>
          <label class="check"><input type="checkbox" id="optRemoved"${aj.avisar_retirados ? ' checked' : ''}> <span>Productos retirados</span></label>
          <div class="actions"><button class="btn primary" id="saveMon">Guardar</button></div>
          <div id="monMsg"></div>
        </form>
      </aside>
    </div>`;
    $('addForm').addEventListener('submit', async (ev) => {
      ev.preventDefault(); msg('addMsg', ''); $('preview').innerHTML = '';
      if (!$('url').value.trim()) return msg('addMsg', 'Pega primero un enlace');
