    $('watchRows').addEventListener('click', async (ev) => {
      const id = ev.target.closest('[data-del]')?.dataset.del; if (!id) return;
      const x = S.vigilancias.find((v) => v.id === id);
      if (!confirm(`¿Dejar de vigilar «${x.nombre}»?`)) return;
      const d = await api('borrar_vigilancia', { id }); if (!d.ok) return toast(d.error);
