  }
  function filasMonitor() {
    return S.vigilancias.map((w) => {
      const e = w.estado;
      const gana = e && w.mi_precio && e.precio !== null && e.precio !== undefined && e.precio < w.mi_precio * (1 - (w.tolerancia_pct || 0) / 100);
      const badge = !e ? '<span class="badge info">Pendiente</span>'
        : e.error && e.fallos ? `<span class="badge bad" title="${esc(e.error)}">Error</span>`
        : e.retirado ? '<span class="badge warn">No disponible</span>'
        : gana ? `<span class="badge bad">Te gana ${Math.abs(Math.round((e.precio - w.mi_precio) / w.mi_precio * 1000) / 10).toLocaleString('es-ES')} %</span>`
        : `<span class="badge ok">${e.productos > 1 ? e.productos.toLocaleString('es-ES') + ' productos' : 'OK'}</span>`;
      const tienda = /tienda$/.test(w.tipo);
