      const mio = tienda ? '<span class="hint">—</span>'
        : `<form class="price-edit" data-id="${esc(w.id)}"><input aria-label="Tu precio" inputmode="decimal" name="p" value="${w.mi_precio ?? ''}" placeholder="—"><button class="btn sm" type="submit">OK</button></form>`;
