    }).join('') || '<tr><td colspan="5" class="empty">Todavía no vigilas nada. Pega arriba el enlace de un producto o de una tienda.</td></tr>';
  }
  function renderPreview(d) {
    const tienda = /tienda$/.test(d.tipo);
    const items = (d.productos || []).map((x) => `<li>${x.image ? `<img src="${esc(x.image)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.visibility='hidden'">` : '<span class="ph"></span>'}
