  // ---------------------------------------------------------------- avisos
  function renderAvisos(p) {
    const bot = BOT && !BOT.startsWith('__') ? `https://t.me/${BOT}` : '';
    p.innerHTML = `<div class="p-grid">
      <form class="p-card" id="setForm" novalidate>
        <p class="eyebrow">Avisos</p>
