        const r = await api('ajustes', { email: $('email').value, telegram_chat_id: $('chat').value });
        if (!r.ok) return msg('setMsg', r.error);
        toast('Avisos guardados'); await load(true); msg('setMsg', 'Guardado', 'ok');
      });
    });
    $('testBtn').addEventListener('click', async (ev) => {
      msg('setMsg', '');
      await busy(ev.currentTarget, 'Enviando', async () => {
        const r = await api('probar_aviso');
        msg('setMsg', r.ok ? r.mensaje : r.error, r.ok ? 'ok' : 'err');
      });
    });
  }

  // ---------------------------------------------------------------- carga
  async function load(keep) {
    const r = await api('estado');
    if (!r.ok) { $('app').innerHTML = `<div class="center"><div><p class="eyebrow" style="justify-content:center">Denoro Automations</p><h1>No se puede abrir tu panel</h1><p class="lead">${esc(r.error)}</p></div></div>`; return; }
    const first = !S; S = r;
    if (first || !keep) { shell(); go(location.hash.slice(1) || 'resumen'); return; }
    const y = window.scrollY; shell(); go(tab); window.scrollTo(0, y);
  }
  document.addEventListener('click', (e) => {
    const t = e.target.closest('[data-tab]'); if (t) { go(t.dataset.tab, true); return; }
    const g = e.target.closest('[data-go]'); if (g) { go(g.dataset.go, true); }
  });
  document.addEventListener('keydown', (e) => {
    if (!e.target.matches?.('.tab') || !['ArrowRight', 'ArrowLeft'].includes(e.key)) return;
    const tabs = [...document.querySelectorAll('.tab')]; const i = tabs.indexOf(e.target);
    const n = tabs[(i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length]; n.focus(); go(n.dataset.tab);
    document.getElementById(`tab-${n.dataset.tab}`)?.focus();
  });
  window.addEventListener('hashchange', () => { if (S && location.hash.slice(1) !== tab) go(location.hash.slice(1)); });

  if (!token) $('app').innerHTML = '<div class="center"><div><p class="eyebrow" style="justify-content:center">Denoro Automations</p><h1>Falta tu enlace de acceso</h1><p class="lead">Abre el enlace personal que te envié desde Denoro.</p></div></div>';
  else load();
})();
</script>
</body>
</html>
" } }];

return [{ json: { html: "<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
