<meta name="theme-color" content="#fcfcfa">
<title>Administración · Denoro Automations</title>
<link rel="icon" href="https://denoroautomations.com/assets/favicon.svg" type="image/svg+xml">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
<style>/* ============================================================
   Denoro Automations · sistema visual
   Papel cálido, tinta, un único acento (verde pizarra).
   Filete de 1 px en lugar de sombras. Instrument Serif + IBM Plex Sans.
   ============================================================ */
:root{
  /* papel y tinta */
  --paper:#fcfcfa; --surface:#fff; --sunk:#f4f3ef;
  --ink:#191713; --text:#35322c; --muted:#6e6a61; --faint:#767166;
  --rule:#e7e4dc; --rule-strong:#d8d4c9; --rule-field:#8f8a7e;
  /* acento único */
  --accent:#235b54; --accent-ink:#fff; --accent-tint:#e8efec; --accent-deep:#1a4640;
  /* estados de formulario (no decorativos) */
  --alert:#8f2f24; --alert-tint:#f8eae7; --ok:#2c5f3c; --ok-tint:#e9f0ea;
  /* radios: contenedores más suaves que los elementos internos */
  --r-xs:4px; --r-s:6px; --r-m:10px; --r-l:14px;
  /* espaciado 4·8·12·16·24·32·48·72·112 */
  --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px; --s6:32px; --s7:48px; --s8:72px; --s9:112px;
  /* escala tipográfica */
  --t-display:clamp(38px,5.4vw,62px); --t-h2:clamp(28px,3.6vw,38px); --t-h3:22px;
  --t-lead:19px; --t-body:17px; --t-sm:15px; --t-xs:13px;
  /* movimiento */
  --e-out:cubic-bezier(.2,.7,.3,1); --d-fast:120ms; --d-base:180ms; --d-enter:320ms;
  --z-header:20; --z-cta:25; --z-cookies:30;
}
html{color-scheme:light}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--text);
  font-family:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;
  font-size:var(--t-body);line-height:1.65;font-feature-settings:"kern" 1;
  -webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:var(--accent);text-decoration-thickness:1px;text-underline-offset:3px}
a:hover{color:var(--accent-deep)}
.wrap{max-width:1140px;margin:0 auto;padding-inline:24px}
@media (max-width:520px){.wrap{padding-inline:20px}}
main{display:block}
section{padding-block:var(--s9) var(--s8)}
section+section{border-top:1px solid var(--rule)}
@media (max-width:720px){section{padding-block:var(--s8) var(--s7)}}

/* --- tipografía --- */
h1,h2,h3{color:var(--ink);margin:0;text-wrap:balance}
h1,h2{font-family:"Instrument Serif","Iowan Old Style",Georgia,serif;font-weight:400;letter-spacing:-.02em}
h1{font-size:var(--t-display);line-height:1.04;max-width:15ch}
h2{font-size:var(--t-h2);line-height:1.12;max-width:20ch}
h3{font-size:var(--t-h3);line-height:1.3;font-weight:600;letter-spacing:-.01em}
p{margin:0;text-wrap:pretty}
.lead{font-size:var(--t-lead);line-height:1.6;color:var(--muted);max-width:56ch}
.eyebrow{display:flex;align-items:center;gap:10px;font-size:12px;font-weight:500;line-height:1;
  letter-spacing:.14em;text-transform:uppercase;color:var(--faint);margin-bottom:var(--s4)}
.eyebrow::after{content:"";flex:1;height:1px;background:var(--rule);max-width:120px}
.hint{color:var(--muted);font-size:var(--t-xs);line-height:1.5}
.num{font-variant-numeric:tabular-nums;font-feature-settings:"tnum" 1,"lnum" 1}
.stack>*+*{margin-top:var(--s4)}

/* --- cabecera (la misma en todas las páginas: src/partials/header.html) --- */
.site-header{position:sticky;top:0;z-index:var(--z-header);background:color-mix(in srgb,var(--paper) 90%,transparent);
  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-bottom:1px solid var(--rule)}
.site-header .wrap{display:flex;align-items:center;gap:var(--s5);min-height:68px;position:relative}
.brand{display:flex;align-items:center;gap:10px;color:var(--ink);text-decoration:none;font-weight:600;font-size:17px;letter-spacing:-.01em;flex:none}
.brand i{width:28px;height:28px;border-radius:var(--r-s);background:var(--accent);color:#fff;
  display:grid;place-items:center;font-style:normal;font-weight:600;font-size:15px;font-family:"Instrument Serif",serif}
.brand span{color:var(--muted);font-weight:400;font-size:14px;letter-spacing:.02em}
.menu{display:flex;gap:var(--s5);margin-left:auto;align-items:center}
.menu a{color:var(--muted);text-decoration:none;font-size:var(--t-sm);white-space:nowrap;transition:color var(--d-fast) var(--e-out)}
.menu a:not(.btn):hover{color:var(--ink)}
.menu a[aria-current]{color:var(--ink);box-shadow:inset 0 -1px 0 var(--accent)}
.menu .menu-cta{display:none}
.header-actions{display:flex;align-items:center;gap:var(--s3);flex:none}
.menu-btn{display:none;align-items:center;gap:8px;min-height:44px;padding:0 12px;border:1px solid var(--rule-field);
  border-radius:var(--r-s);background:var(--surface);color:var(--ink);font:500 14px/1 "IBM Plex Sans",sans-serif;cursor:pointer}
.menu-btn:hover{border-color:var(--ink)}
.menu-icon,.menu-icon::before,.menu-icon::after{display:block;width:16px;height:1.5px;background:currentColor;border-radius:1px;
  transition:transform var(--d-base) var(--e-out),opacity var(--d-fast) var(--e-out)}
.menu-icon{position:relative}
.menu-icon::before,.menu-icon::after{content:"";position:absolute;left:0}
.menu-icon::before{top:-5px}.menu-icon::after{top:5px}
.menu-btn[aria-expanded="true"] .menu-icon{background:transparent}
.menu-btn[aria-expanded="true"] .menu-icon::before{transform:translateY(5px) rotate(45deg)}
.menu-btn[aria-expanded="true"] .menu-icon::after{transform:translateY(-5px) rotate(-45deg)}
/* por debajo de 1100 px no caben los cinco apartados: van a un menú desplegable */
@media (max-width:1100px){
  .js .menu-btn{display:inline-flex}
  .js .menu{position:absolute;top:100%;left:0;right:0;margin:0;display:none;flex-direction:column;align-items:stretch;gap:0;
    background:var(--surface);border-bottom:1px solid var(--rule);padding:var(--s2) 24px var(--s5);
    box-shadow:0 12px 24px -16px rgba(25,23,19,.25)}
  .js .menu.open{display:flex;animation:menu-in var(--d-base) var(--e-out)}
  .js .menu a:not(.btn){display:flex;align-items:center;min-height:52px;font-size:var(--t-body);color:var(--ink);border-bottom:1px solid var(--rule)}
  .js .menu a[aria-current]{box-shadow:inset 3px 0 0 var(--accent);padding-left:12px}
  .js .menu .menu-cta{display:inline-flex;margin-top:var(--s4)}
  .js .header-actions{margin-left:auto}
  html:not(.js) .site-header .wrap{flex-wrap:wrap;padding-block:var(--s3)}
  html:not(.js) .menu{order:3;width:100%;flex-wrap:wrap;gap:var(--s2) var(--s4);margin:0}
}
@keyframes menu-in{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
@media (max-width:620px){.site-header .wrap{gap:var(--s3)}.header-actions .header-cta{display:none}.brand span{display:none}
  .js .menu{padding-inline:20px}}
@media (max-width:360px){.menu-btn [data-i18n]{display:none}.menu-btn{padding:0 13px}}

/* --- selector de idioma --- */
.lang{display:inline-flex;border:1px solid var(--rule-field);border-radius:var(--r-s);overflow:hidden;background:var(--surface)}
.lang button{border:0;background:transparent;color:var(--muted);cursor:pointer;
  font:500 13px/1 "IBM Plex Sans",sans-serif;letter-spacing:.04em;padding:0 13px;min-height:44px;
  transition:color var(--d-fast) var(--e-out),background var(--d-fast) var(--e-out)}
.lang button:hover{color:var(--ink)}
.lang button[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink)}

/* --- botones --- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;padding:0 20px;
  border:1px solid var(--rule-field);border-radius:var(--r-s);background:var(--surface);color:var(--ink);
  font:500 16px/1 "IBM Plex Sans",sans-serif;text-decoration:none;cursor:pointer;white-space:nowrap;
  transition:background var(--d-base) var(--e-out),border-color var(--d-base) var(--e-out),
             color var(--d-base) var(--e-out),transform 80ms var(--e-out)}
.btn:hover{background:var(--sunk);border-color:var(--ink)}
.btn:active{transform:scale(.985)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.btn.primary:hover{background:var(--accent-deep);border-color:var(--accent-deep)}
.btn.ghost{background:transparent;border-color:transparent;color:var(--muted)}
.btn.ghost:hover{background:var(--sunk);color:var(--ink)}
.btn:disabled{opacity:.5;cursor:progress}
:where(a,button,input,select,textarea,summary,details):focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:var(--r-xs)}
.skip{position:absolute;left:-9999px}
.skip:focus{left:24px;top:12px;z-index:40;background:var(--surface);padding:12px 16px;border:1px solid var(--rule);border-radius:var(--r-s)}

/* --- movimiento: entrada al hacer scroll --- */
.reveal{opacity:0;transform:translateY(8px)}
.reveal.in{opacity:1;transform:none;transition:opacity var(--d-enter) var(--e-out),transform var(--d-enter) var(--e-out);
  transition-delay:var(--delay,0ms)}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
  .reveal{opacity:1;transform:none}
}

/* --- portada --- */
.hero{padding-block:var(--s8) var(--s9);border-top:0}
.hero-grid{display:grid;gap:var(--s7);align-items:center}
@media (min-width:1000px){
  .hero-grid{grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:var(--s6);align-items:center}
  .hero-shot{margin-right:calc(-1 * var(--s7))}
}
.hero-copy h1{margin-bottom:var(--s4)}
.cta-row{display:flex;gap:var(--s3);flex-wrap:wrap;margin-top:var(--s5)}
.facts{display:grid;gap:0;margin:var(--s6) 0 0;border-top:1px solid var(--rule)}
.facts>div{display:grid;grid-template-columns:minmax(88px,auto) 1fr;gap:var(--s4);
  padding-block:var(--s3);border-bottom:1px solid var(--rule)}
.facts dt{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);padding-top:3px}
.facts dd{margin:0;font-size:var(--t-sm);color:var(--text)}
.facts .num{color:var(--ink);font-weight:600}
/* marco de ventana para las capturas */
.window{border:1px solid var(--rule);border-radius:var(--r-l);overflow:hidden;background:var(--surface)}
.window-bar{display:flex;align-items:center;gap:6px;padding:10px 14px;border-bottom:1px solid var(--rule);background:var(--sunk)}
.window-bar span{width:9px;height:9px;border-radius:50%;background:var(--rule-strong)}
.window-bar b{margin-left:8px;font:400 12px/1 "IBM Plex Sans",sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
figure{margin:0}
figcaption{color:var(--faint);font-size:var(--t-xs);margin-top:var(--s3);max-width:52ch}

/* --- pasos --- */
.steps{list-style:none;margin:var(--s7) 0 0;padding:0;border-top:1px solid var(--rule)}
.steps li{display:grid;grid-template-columns:auto minmax(0,1fr);gap:var(--s5);
  padding-block:var(--s6);border-bottom:1px solid var(--rule);align-items:start}
@media (min-width:860px){.steps li{grid-template-columns:96px minmax(0,26ch) minmax(0,1fr);gap:var(--s6);align-items:baseline}
  .steps li>div{display:contents}
  .steps h3{margin:0}
}
.step-n{font-family:"Instrument Serif",Georgia,serif;font-size:34px;line-height:1;color:var(--accent)}
.steps p{color:var(--muted);max-width:52ch}
@media (max-width:859px){.steps h3{margin-bottom:var(--s2)}}

/* --- qué te avisa --- */
.detects{margin-top:var(--s7);display:grid;gap:var(--s4)}
@media (min-width:860px){.detects{grid-template-columns:96px minmax(0,1fr);gap:var(--s6);align-items:baseline}}
.detects-label{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint)}
.chips{list-style:none;display:flex;flex-wrap:wrap;gap:var(--s2);margin:0;padding:0}
.chips li{border:1px solid var(--rule);border-radius:999px;padding:7px 14px;font-size:var(--t-sm);
  color:var(--ink);background:var(--surface)}

/* --- demos --- */
.demo{display:grid;gap:var(--s6);margin-top:var(--s7);align-items:center}
@media (min-width:920px){
  .demo{grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:var(--s7)}
  .demo.rev>figure{order:2}
  .demo-copy{max-width:46ch}
}
.demo-copy h3{margin-bottom:var(--s3)}
.demo-copy .facts{margin-top:var(--s5)}
.link-arrow{display:inline-flex;align-items:center;gap:8px;font-weight:500;text-decoration:none;
  border-bottom:1px solid currentColor;padding-bottom:2px}
.link-arrow::after{content:"→";transition:transform var(--d-base) var(--e-out)}
.link-arrow:hover::after{transform:translateX(3px)}
/* mensaje de Telegram (maqueta) */
.tg{border:1px solid var(--rule);border-radius:var(--r-l);background:var(--surface);padding:var(--s4);max-width:420px}
.tg-head{display:flex;align-items:center;gap:10px;padding-bottom:var(--s3);border-bottom:1px solid var(--rule);margin-bottom:var(--s3)}
.tg-head i{width:34px;height:34px;border-radius:var(--r-s);background:var(--accent);color:#fff;
  display:grid;place-items:center;font-style:normal;font-family:"Instrument Serif",serif;font-size:17px}
.tg-head b{color:var(--ink);font-size:var(--t-sm);font-weight:600}
.tg-head span{display:block;color:var(--faint);font-size:12px}
.tg-msg{background:var(--sunk);border-radius:var(--r-s);padding:var(--s3) var(--s4);font-size:14.5px;
  line-height:1.6;color:var(--text);white-space:pre-wrap}
.tg-msg b{color:var(--ink);font-weight:600}

/* --- precios --- */
.plans{display:grid;gap:var(--s5);margin-top:var(--s7);align-items:stretch}
@media (min-width:880px){.plans{grid-template-columns:repeat(3,1fr);gap:0;border:1px solid var(--rule);border-radius:var(--r-l);overflow:hidden}
  .plan+.plan{border-left:1px solid var(--rule)}
}
.plan{display:flex;flex-direction:column;gap:var(--s4);padding:var(--s6) var(--s5);background:var(--surface);
  border:1px solid var(--rule);border-radius:var(--r-l)}
@media (min-width:880px){.plan{border:0;border-radius:0}}
.plan.featured{background:var(--sunk)}
.plan header{display:grid;gap:var(--s1);min-height:118px;align-content:start}
@media (max-width:879px){.plan header{min-height:0;margin-bottom:var(--s2)}}
.plan-tag{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint)}
.plan.featured .plan-tag{color:var(--accent)}
.price{font-family:"Instrument Serif",Georgia,serif;font-size:42px;line-height:1.05;color:var(--ink);letter-spacing:-.02em}
.price small{font-family:"IBM Plex Sans",sans-serif;font-size:14px;color:var(--muted);letter-spacing:0;margin-left:6px}
.plan-sub{font-size:var(--t-xs);color:var(--muted)}
.plan ul{list-style:none;margin:0;padding:0;display:grid;gap:12px;font-size:var(--t-sm);color:var(--text);flex:1}
.plan li{display:grid;grid-template-columns:18px 1fr;gap:10px;align-items:baseline}
.plan li::before{content:"";width:6px;height:6px;margin-left:5px;border-radius:50%;background:var(--accent);opacity:.45;transform:translateY(-2px)}
.plan.featured li::before{background:var(--accent);opacity:1}
.plan .btn{margin-top:var(--s2)}
.note{margin-top:var(--s5);color:var(--muted);font-size:var(--t-sm);max-width:70ch}

/* --- preguntas --- */
.faq{margin-top:var(--s7);border-top:1px solid var(--rule)}
details{border-bottom:1px solid var(--rule);padding-block:var(--s4)}
summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:var(--s4);
  font-size:var(--t-lead);color:var(--ink);min-height:36px;transition:color var(--d-fast) var(--e-out)}
summary:hover{color:var(--accent)}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";font-size:22px;line-height:1;color:var(--faint);transition:transform var(--d-base) var(--e-out)}
details[open] summary::after{content:"−";transform:rotate(180deg)}
details p{margin-top:var(--s3);color:var(--muted);max-width:72ch;font-size:var(--t-sm)}
details[open] p{animation:faq-in var(--d-enter) var(--e-out) both}
@keyframes faq-in{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}

/* --- formulario --- */
.form-grid{display:grid;gap:var(--s7);align-items:start}
@media (min-width:920px){.form-grid{grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:var(--s8)}}
.form-intro .lead{margin-top:var(--s4)}
.form-card{background:var(--surface);border:1px solid var(--rule);border-radius:var(--r-l);padding:var(--s6)}
@media (max-width:520px){.form-card{padding:var(--s5) var(--s4)}}
form .row{display:grid;gap:var(--s4);grid-template-columns:1fr 1fr}
@media (max-width:640px){form .row{grid-template-columns:1fr}}
label{display:block;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--faint);margin-bottom:6px}
input,select,textarea{width:100%;font:inherit;font-size:16px;color:var(--text);background:var(--paper);
  border:1px solid var(--rule-field);border-radius:var(--r-s);padding:12px 14px;min-height:50px;
  transition:border-color var(--d-base) var(--e-out),background var(--d-base) var(--e-out)}
input:hover,select:hover,textarea:hover{border-color:var(--ink)}
input:focus,select:focus,textarea:focus{background:var(--surface)}
[aria-invalid="true"]{border-color:var(--alert);background:var(--alert-tint)}
textarea{min-height:104px;resize:vertical;line-height:1.55}
.field{margin-bottom:var(--s4)}
.field .hint{margin-top:6px}
.consent{display:flex;gap:10px;align-items:flex-start;margin:var(--s3) 0 var(--s5);
  font-size:var(--t-xs);line-height:1.55;color:var(--muted);text-transform:none;letter-spacing:0}
.consent input{width:22px;height:22px;min-height:0;margin-top:0;flex:none;accent-color:var(--accent)}
.msg{margin-top:var(--s4);padding:12px 14px;border-radius:var(--r-s);font-size:var(--t-sm);border:1px solid}
.msg.ok{background:var(--ok-tint);color:var(--ok);border-color:transparent}
.msg.err{background:var(--alert-tint);color:var(--alert);border-color:transparent}
.checklist{list-style:none;margin:var(--s6) 0 0;padding:0;display:grid;
  color:var(--muted);font-size:var(--t-sm);border-top:1px solid var(--rule)}
.checklist li{display:grid;grid-template-columns:minmax(120px,auto) 1fr;gap:var(--s4);
  padding-block:var(--s3);border-bottom:1px solid var(--rule);align-items:baseline}
.checklist b{color:var(--ink);font-weight:600}
@media (max-width:520px){.checklist li{grid-template-columns:1fr;gap:2px}}

/* --- pie --- */
footer{padding-block:var(--s7);border-top:1px solid var(--rule);color:var(--muted);font-size:var(--t-xs)}
footer .wrap{display:flex;gap:var(--s5);flex-wrap:wrap;align-items:center;justify-content:space-between}
footer a{color:var(--muted);text-decoration:none;border-bottom:1px solid var(--rule)}
footer a:hover{color:var(--ink);border-color:var(--ink)}

/* --- barra de contacto en móvil --- */
.mobile-cta{position:fixed;left:0;right:0;bottom:0;z-index:var(--z-cta);
  background:color-mix(in srgb,var(--paper) 94%,transparent);backdrop-filter:blur(10px);
  border-top:1px solid var(--rule);padding:10px 16px;padding-bottom:calc(10px + env(safe-area-inset-bottom,0px));
  animation:cta-in var(--d-base) var(--e-out)}
@keyframes cta-in{from{opacity:0;transform:translateY(100%)}to{opacity:1;transform:none}}
.mobile-cta .btn{width:100%}
@media (min-width:901px){.mobile-cta{display:none!important}}
body.has-mobile-cta footer{padding-bottom:96px}

/* --- aviso de cookies --- */
.cookies{position:fixed;left:0;right:0;bottom:0;z-index:var(--z-cookies);background:var(--surface);
  border-top:1px solid var(--rule);padding-block:var(--s4);padding-bottom:calc(var(--s4) + env(safe-area-inset-bottom,0px));
  animation:cookies-in var(--d-enter) var(--e-out) both}
@keyframes cookies-in{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.cookie-inner{display:flex;gap:var(--s4);align-items:center;justify-content:space-between;flex-wrap:wrap}
.cookie-inner p{font-size:var(--t-xs);color:var(--muted);max-width:64ch}
.cookie-actions{display:flex;gap:var(--s2);flex-wrap:wrap}
.cookie-actions .btn{min-height:44px;font-size:var(--t-sm)}
@media (max-width:860px){
  .cookies{padding-block:var(--s3)}
  .cookie-actions{width:100%}
  .cookie-actions .btn{flex:1 1 auto;padding-inline:12px}
}

/* --- páginas legales --- */
.legal{padding-block:var(--s7) var(--s9);max-width:760px}
.legal h1{max-width:22ch;font-size:clamp(32px,4.4vw,46px);margin-bottom:var(--s3)}
.legal section{margin-top:var(--s7);border-top:0;padding:0}
.legal h2{padding-top:var(--s5);border-top:1px solid var(--rule);max-width:none}
.legal h3{margin-top:var(--s5);font-size:17px}
.legal p{margin-top:var(--s3);max-width:68ch}
.legal .checklist{border-top:0;padding-top:0}

/* en móvil, la captura del panel es la versión de móvil: se lee */
@media (max-width:640px){.demo picture img{max-height:520px;object-fit:cover;object-position:top}}

/* captura del email dentro del bloque de avisos */
.mail-shot{margin-top:var(--s5);max-width:340px}
.mail-shot .window img{max-height:260px;object-fit:cover;object-position:top}

/* --- anclas: que la cabecera fija no tape el título al saltar --- */
section[id],[id].auto{scroll-margin-top:84px}
.section-lead{margin-top:var(--s4)}

/* --- índice de las siete (portada y catálogo) --- */
.hero-index{border:1px solid var(--rule);border-radius:var(--r-l);background:var(--surface);padding:var(--s5) var(--s5) var(--s4)}
.hero-index-head{display:flex;justify-content:space-between;gap:var(--s4);font-size:12px;letter-spacing:.1em;text-transform:uppercase;
  color:var(--faint);padding-bottom:var(--s3);border-bottom:1px solid var(--rule)}
.hero-index ol{list-style:none;margin:0;padding:0}
.hero-index li{border-bottom:1px solid var(--rule)}
.hero-index a{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:var(--s3);align-items:baseline;
  padding-block:var(--s3);min-height:48px;color:var(--ink);text-decoration:none;transition:color var(--d-fast) var(--e-out)}
.hi-n{font-family:"Instrument Serif",Georgia,serif;font-size:19px;color:var(--accent)}
.hi-t{font-size:var(--t-sm);font-weight:500;line-height:1.4}
.hi-c{font-size:var(--t-xs);color:var(--muted);white-space:nowrap;text-align:right}
.hero-index a:hover .hi-t{color:var(--accent);text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
.hero-index-foot{margin-top:var(--s3);font-size:var(--t-xs);color:var(--muted)}
@media (max-width:420px){.hero-index{padding:var(--s4)}.hero-index a{grid-template-columns:28px minmax(0,1fr)}.hi-c{grid-column:2;text-align:left;margin-top:-6px}}

/* --- rejilla de automatizaciones en la portada --- */
.auto-grid{list-style:none;margin:var(--s7) 0 0;padding:0;display:grid;gap:var(--s5);grid-template-columns:repeat(4,minmax(0,1fr))}
