.autos{display:grid;gap:var(--s5);grid-template-columns:repeat(2,minmax(0,1fr))}
@media (max-width:860px){.autos{grid-template-columns:1fr}}
.auto{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--rule);
  border-radius:var(--r-l);padding:var(--s3) var(--s5) var(--s5)}
.auto-shot{border:1px solid var(--rule);border-radius:var(--r-m);overflow:hidden;background:var(--sunk);aspect-ratio:16/10;
  margin:0 calc(var(--s2) - var(--s5)) var(--s5)}
.auto-shot img{width:100%;height:100%;object-fit:cover;object-position:top left}
.auto>.eyebrow{margin-bottom:var(--s3);font-size:12px;color:var(--faint)}
.auto h2{font-size:26px;font-family:"Instrument Serif","Iowan Old Style",Georgia,serif;
  font-weight:400;letter-spacing:-.01em;max-width:none;margin-bottom:var(--s3)}
.auto>p:not(.eyebrow){color:var(--text);font-size:var(--t-sm);line-height:1.6}
.auto .checklist{margin-top:var(--s4);font-size:var(--t-xs)}
