.card-head{display:flex;align-items:baseline;justify-content:space-between;gap:var(--s3);flex-wrap:wrap;margin-bottom:var(--s4)}

/* --- formularios --- */
fieldset{border:0;margin:0;padding:0;min-width:0}
fieldset+fieldset{margin-top:var(--s5);padding-top:var(--s5);border-top:1px solid var(--rule)}
legend{padding:0;margin-bottom:var(--s4);font-size:12px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--faint)}
.fgrid{display:grid;gap:0 var(--s4)}
@media (min-width:640px){.fgrid{grid-template-columns:1fr 1fr}.fgrid .full{grid-column:1/-1}}
.check{display:flex;gap:12px;align-items:flex-start;padding-block:10px;cursor:pointer;
  font-size:var(--t-sm);line-height:1.5;color:var(--text);text-transform:none;letter-spacing:0;margin:0}
