.note{font-size:var(--t-xs);color:var(--muted);margin-top:var(--s3);max-width:none}
.msg{font-size:var(--t-sm)}
.msg.warn{background:#f4eee1;color:#7a5a1c;border-color:transparent}

/* --- tarjetas del resumen (las del catálogo de la web) --- */
.autos.panel{grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.auto .auto-state{display:flex;gap:var(--s2);align-items:center;flex-wrap:wrap;margin:0 0 var(--s3)}
.auto button.link-arrow{background:none;border:0;border-bottom:1px solid currentColor;cursor:pointer;font:inherit;font-weight:500;padding:0 0 2px}
.auto .auto-meta{margin-top:auto;margin-bottom:var(--s4)}
.auto>p{margin-bottom:var(--s4)}

/* --- tablas --- */
.tbl-wrap{overflow-x:auto;margin-inline:calc(-1 * var(--s2))}
table.tbl{width:100%;border-collapse:collapse;font-size:var(--t-sm)}
.tbl th{font-size:12px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);text-align:left;
  padding:0 var(--s2) 10px;border-bottom:1px solid var(--rule);white-space:nowrap}
.tbl td{padding:14px var(--s2);border-bottom:1px solid var(--rule);vertical-align:top}
.tbl tr:last-child td{border-bottom:0}
.tbl .r{text-align:right}
.tbl .name{font-weight:500;color:var(--ink);word-break:break-word}
.tbl .sub{font-size:var(--t-xs);color:var(--muted);word-break:break-all;margin-top:2px}
.tbl tr.open td{background:var(--sunk)}
.tbl tr.edit td{background:var(--sunk);padding-top:0}
.num{font-variant-numeric:tabular-nums}
.empty{padding:var(--s6) var(--s3);text-align:center;color:var(--muted);font-size:var(--t-sm)}
@media (max-width:640px){.hide-s{display:none}}

/* --- monitor: vista previa de lo detectado --- */
.preview{margin-top:var(--s4);border:1px solid var(--rule);border-radius:var(--r-m);overflow:hidden;background:var(--paper)}
.preview-head{padding:var(--s3) var(--s4);background:var(--sunk);display:flex;gap:var(--s3);align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--rule)}
.preview-body{padding:var(--s2) var(--s4) var(--s4)}
.plist{list-style:none;margin:0;padding:0}
.plist li{display:flex;gap:var(--s3);align-items:center;padding:10px 0;border-bottom:1px solid var(--rule);font-size:var(--t-sm)}
.plist li:last-child{border-bottom:0}
.plist img,.plist .ph{width:40px;height:40px;object-fit:cover;border-radius:var(--r-s);background:var(--sunk);flex:none}
.plist .p{margin-left:auto;text-align:right;white-space:nowrap}
.price-edit{display:flex;gap:6px;align-items:center;justify-content:flex-end}
.price-edit input{width:100px;min-height:40px;padding:6px 10px;text-align:right;font-size:15px}
.kinds{list-style:none;margin:var(--s3) 0 0;padding:0;display:grid;gap:6px;font-size:var(--t-xs);color:var(--muted)}
.kinds b{color:var(--ink);font-weight:500}

/* --- estados de página --- */
.center{min-height:62vh;display:grid;place-items:center;text-align:center;padding-block:var(--s7)}
.center h1{margin-inline:auto}
.center .lead{margin:var(--s3) auto 0}
.login{width:min(420px,100%);text-align:left}
.login h2{font-size:var(--t-h2)}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,8px);background:var(--ink);color:var(--paper);
  padding:12px 18px;border-radius:var(--r-s);font-size:var(--t-sm);opacity:0;pointer-events:none;max-width:90vw;z-index:50;
  transition:opacity var(--d-base) var(--e-out),transform var(--d-base) var(--e-out)}
.toast.show{opacity:1;transform:translate(-50%,0)}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.spin{display:inline-block;width:14px;height:14px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
body.app footer{padding-block:var(--s5)}
[hidden]{display:none!important}
.chips li.ok{background:var(--ok-tint);color:var(--ok);border-color:transparent}
.chips li.bad{background:var(--alert-tint);color:var(--alert);border-color:transparent}
.tbl td:first-child{min-width:170px}
.tbl .chips{max-width:420px}
</style>
